"use client";

import { useCallback, useEffect, useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Cropper,
	CropperCropArea,
	CropperDescription,
	CropperImage,
} from "@/components/ui/cropper";

// Define type for pixel crop area
type Area = { x: number; y: number; width: number; height: number };

// --- Start: Copied Helper Functions ---
const createImage = (url: string): Promise<HTMLImageElement> =>
	new Promise((resolve, reject) => {
		const image = new Image();
		image.addEventListener("load", () => resolve(image));
		image.addEventListener("error", (error) => reject(error));
		image.setAttribute("crossOrigin", "anonymous"); // Needed for canvas Tainted check
		image.src = url;
	});

async function getCroppedImg(
	imageSrc: string,
	pixelCrop: Area,
	outputWidth: number = pixelCrop.width, // Optional: specify output size
	outputHeight: number = pixelCrop.height
): Promise<Blob | null> {
	try {
		const image = await createImage(imageSrc);
		const canvas = document.createElement("canvas");
		const ctx = canvas.getContext("2d");

		if (!ctx) {
			return null;
		}

		// Set canvas size to desired output size
		canvas.width = outputWidth;
		canvas.height = outputHeight;

		// Draw the cropped image onto the canvas
		ctx.drawImage(
			image,
			pixelCrop.x,
			pixelCrop.y,
			pixelCrop.width,
			pixelCrop.height,
			0,
			0,
			outputWidth, // Draw onto the output size
			outputHeight
		);

		// Convert canvas to blob
		return new Promise((resolve) => {
			canvas.toBlob((blob) => {
				resolve(blob);
			}, "image/jpeg"); // Specify format and quality if needed
		});
	} catch (error) {
		console.error("Error in getCroppedImg:", error);
		return null;
	}
}
// --- End: Copied Helper Functions ---

const ORIGINAL_IMAGE_URL =
	"https://raw.githubusercontent.com/origin-space/origin-images/refs/heads/main/cropper-10_k24zxk.jpg";

export default function Component() {
	const [croppedAreaPixels, setCroppedAreaPixels] = useState<Area | null>(
		null
	);
	const [croppedImageUrl, setCroppedImageUrl] = useState<string | null>(null);

	// Callback to update crop area state
	const handleCropChange = useCallback((pixels: Area | null) => {
		setCroppedAreaPixels(pixels);
	}, []);

	// Function to handle the crop button click
	const handleCrop = async () => {
		if (!croppedAreaPixels) {
			console.error("No crop area selected.");
			return;
		}

		try {
			const croppedBlob = await getCroppedImg(
				ORIGINAL_IMAGE_URL,
				croppedAreaPixels
			);
			if (!croppedBlob) {
				throw new Error("Failed to generate cropped image blob.");
			}

			// Create a new object URL
			const newCroppedUrl = URL.createObjectURL(croppedBlob);

			// Revoke the old URL if it exists
			if (croppedImageUrl) {
				URL.revokeObjectURL(croppedImageUrl);
			}

			// Set the new URL
			setCroppedImageUrl(newCroppedUrl);
		} catch (error) {
			console.error("Error during cropping:", error);
			// Optionally: Clear the old image URL on error
			if (croppedImageUrl) {
				URL.revokeObjectURL(croppedImageUrl);
			}
			setCroppedImageUrl(null);
		}
	};

	// Effect for cleaning up the object URL
	useEffect(() => {
		// This is the cleanup function that runs when the component unmounts
		// or when croppedImageUrl changes before the next effect runs.
		const currentUrl = croppedImageUrl;
		return () => {
			if (currentUrl && currentUrl.startsWith("blob:")) {
				URL.revokeObjectURL(currentUrl);
				console.log("Revoked URL:", currentUrl); // Optional: for debugging
			}
		};
	}, [croppedImageUrl]); // Dependency array ensures cleanup runs when URL changes

	return (
		<div className="flex flex-col items-center gap-2">
			<div className="flex w-full flex-col gap-4 md:flex-row">
				<Cropper
					className="h-64 md:flex-1"
					image={ORIGINAL_IMAGE_URL}
					onCropChange={handleCropChange}
				>
					<CropperDescription />
					<CropperImage />
					<CropperCropArea />
				</Cropper>
				<div className="flex w-26 flex-col gap-4">
					<Button onClick={handleCrop} disabled={!croppedAreaPixels}>
						Crop preview
					</Button>
					{/* Display Area */}
					<div className="aspect-square w-full shrink-0 overflow-hidden rounded-lg border">
						{croppedImageUrl ? (
							<img
								src={croppedImageUrl}
								alt="Cropped result"
								className="h-full w-full object-cover"
							/>
						) : (
							<div className="bg-muted text-muted-foreground/80 flex h-full w-full items-center justify-center p-2 text-center text-xs">
								Image preview
							</div>
						)}
					</div>
				</div>
			</div>

			<p
				aria-live="polite"
				role="region"
				className="text-muted-foreground mt-2 text-xs"
			>
				Cropper with image preview ∙{" "}
				<a
					href="https://github.com/origin-space/image-cropper"
					className="hover:text-foreground underline"
					target="_blank"
					rel="noopener noreferrer"
				>
					API
				</a>
			</p>
		</div>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
